<?php
namespace App\Jobs;
use App\Imports\DailyReportExcelImport; use App\Imports\DailyReportWorkbookImport; use App\Models\DailyReportImport; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Queue\SerializesModels; use Illuminate\Support\Facades\Storage; use Maatwebsite\Excel\Facades\Excel; use PhpOffice\PhpSpreadsheet\IOFactory; use Throwable;
class ImportDailyReports implements ShouldQueue { use Dispatchable, InteractsWithQueue, Queueable, SerializesModels; public int $tries = 1; public function __construct(private readonly int $importId){} public function handle():void{$record=DailyReportImport::findOrFail($this->importId);$record->update(['status'=>'processing']);$import=new DailyReportExcelImport($record);$path=null;try{$path=Storage::path($record->file_path);if(!is_file($path))throw new \RuntimeException('Import file is not available in shared storage.');$reader=IOFactory::createReaderForFile($path);$reader->setReadDataOnly(true);$book=$reader->load($path);$firstCell=strtoupper(trim((string)$book->getSheet(0)->getCell('A1')->getValue()));$workbook=$firstCell==='TGL PRODUKSI'?$import:new DailyReportWorkbookImport($import);Excel::import($workbook,$path);$import->finish();}catch(Throwable $exception){try{$record->update(['status'=>'failed','error_message'=>$exception->getMessage(),'processed_rows'=>$import->processed(),'imported_reports'=>$import->reports(),'failed_rows'=>count($import->errors())]);}catch(Throwable $updateException){report($updateException);}}finally{if($path!==null&&is_file($path))Storage::delete($record->file_path);}} }
